USE fluviapp;

-- ==========================================================
-- 1. TABLA: rios
-- ==========================================================
ON DUPLICATE KEY UPDATE 
nombre=VALUES(nombre), longitud_total_km=VALUES(longitud_total_km), longitud_navegable_km=VALUES(longitud_navegable_km), 
cuenca=VALUES(cuenca), calado_promedio_pies=VALUES(calado_promedio_pies), departamentos_que_conecta=VALUES(departamentos_que_conecta), 
tipo_embarcaciones=VALUES(tipo_embarcaciones), principales_cargas=VALUES(principales_cargas), importancia=VALUES(importancia);


-- ==========================================================
-- 2. TABLA: muelles
-- ==========================================================
ON DUPLICATE KEY UPDATE 
nombre=VALUES(nombre), rio=VALUES(rio), municipio=VALUES(municipio), departamento=VALUES(departamento), 
latitud=VALUES(latitud), longitud=VALUES(longitud), descripcion=VALUES(descripcion);


-- ==========================================================
-- 3. TABLA: rutas
-- ==========================================================
ON DUPLICATE KEY UPDATE 
muelle_origen_id=VALUES(muelle_origen_id), muelle_destino_id=VALUES(muelle_destino_id), 
distancia_km=VALUES(distancia_km), duracion_estimada_min=VALUES(duracion_estimada_min), tarifa_base=VALUES(tarifa_base);
