INSERT INTO rios (id, nombre, longitud_total_km, longitud_navegable_km, cuenca, calado_promedio_pies, departamentos_que_conecta, tipo_embarcaciones, principales_cargas, importancia, estado)
VALUES
(1, 'Río Magdalena', 1528.00, 908.00, 'Cuenca Caribe/Magdalena', '4.5-7.5 pies', 'Huila, Tolima, Cundinamarca, Caldas, Boyacá, Antioquia, Santander, Bolívar, Cesar, Magdalena, Atlántico', 'convoys, barcazas, chalupas', 'petróleo, cemento, carbón, contenedores', 'Es la principal arteria fluvial de Colombia y su eje económico e histórico. Conecta el interior del país con la costa Caribe, facilitando el transporte de carga pesada.', 'activo'),
(2, 'Río Cauca', 1350.00, 620.00, 'Cuenca Magdalena/Cauca', '3-5.5 pies', 'Cauca, Valle, Risaralda, Caldas, Antioquia, Sucre, Bolívar', 'planchones, lanchas, dragas', 'ganado, arroz, materiales', 'El segundo río más importante de Colombia, fundamental para el desarrollo agrícola y minero de su cuenca. Sirve como fuente de agua y vía de comunicación para cientos de municipios.', 'activo'),
(3, 'Río Atrato', 750.00, 508.00, 'Cuenca Atrato/Pacífico-Caribe', '6-8.5 pies', 'Chocó, Antioquia', 'barcos carga mixta, bongos, pangas', 'madera, plátano, oro, combustible', 'Representa cerca del 85% de la movilidad del departamento del Chocó, siendo una verdadera autopista natural. Es vital para la subsistencia, el comercio y la conexión de comunidades aisladas en la selva pacífica.', 'activo'),
(4, 'Río Meta', 1050.00, 760.00, 'Cuenca Orinoco', '3.5-6.5 pies', 'Meta, Casanare, Arauca, Vichada', 'barcazas, remolcadores, lanchas', 'crudo, agroindustria', 'Eje central de los Llanos Orientales, esencial para la industria de hidrocarburos y la ganadería. Conecta a Colombia con Venezuela y el Orinoco.', 'activo'),
(5, 'Río Guaviare', 1497.00, 630.00, 'Orinoco/Amazonas', '3-5 pies', 'Guaviare, Meta, Guainía, Vichada', 'lanchas voladoras, canoas', 'víveres, combustible, madera', 'Cruza una extensa región selvática, permitiendo el abastecimiento de zonas remotas. Juega un papel clave en el tránsito de mercancías hacia la Orinoquía y Amazonía colombo-venezolana.', 'activo'),
(6, 'Río Putumayo', 1813.00, 1500.00, 'Amazonas', '4-6 pies', 'Putumayo, Amazonas, Frontera Perú/Ecuador', 'barcazas cisterna, lanchas', 'hidrocarburos, comercio binacional', 'Vía de comunicación fronteriza de primer orden, facilitando el intercambio comercial entre Colombia, Perú y Ecuador. Es estratégico para el transporte de crudo.', 'activo'),
(7, 'Río Amazonas', 6400.00, 116.00, 'Amazonas', '>25 pies', 'Amazonas Colombia/Perú/Brasil', 'buques mercantes, ferris', 'comercio ultramar, ecoturismo', 'El río más caudaloso del mundo proporciona a Colombia salida al Océano Atlántico. Es la puerta de entrada para el comercio internacional en el sur del país.', 'activo'),
(8, 'Río Orinoco', 2140.00, 270.00, 'Orinoco', '>10 pies', 'Vichada, Guainía, Venezuela', 'barcos graneleros, voladoras', 'exportación, comercio binacional', 'Límite natural con Venezuela y corredor esencial para la exportación de productos agroindustriales. Su profundidad permite el tránsito de buques de gran calado.', 'activo'),
(9, 'Río San Juan', 380.00, 280.00, 'Pacífico', '5-7 pies', 'Chocó, Valle del Cauca', 'chalupas, canoas', 'madera, plátano, pescado', 'Corredor estratégico para la vertiente del Pacífico, dinamizando el comercio entre el Chocó y el Valle del Cauca. Sustenta la economía de numerosas comunidades afrocolombianas.', 'activo'),
(10, 'Río Sinú', 415.00, 200.00, 'Caribe', '2.5-4 pies', 'Córdoba', 'planchones, Businú, chalupas', 'transporte público urbano, turismo, ganado', 'Atraviesa el fértil valle del mismo nombre, siendo clave para la ganadería y la agricultura de Córdoba. Además, es un atractivo turístico y vía de transporte en Montería.', 'activo'),
(11, 'Río Arauca', 1050.00, 510.00, 'Orinoco', '2.5-4.5 pies', 'Arauca, Venezuela', 'canoas motor, chalupas', 'ganado, cacao, comercio fronterizo', 'Fundamental para el comercio binacional y la integración social entre comunidades de Colombia y Venezuela. Transporta importantes rubros agrícolas de la región llanera.', 'activo'),
(12, 'Río Vaupés', 1050.00, 450.00, 'Amazonas', '2.5-3.5 pies', 'Guaviare, Vaupés, Brasil', 'chalupas fibra, canoas madera', 'víveres, medicamentos, pescado', 'Principal arteria para el departamento del Vaupés, permitiendo el ingreso de productos de primera necesidad. Es indispensable para la subsistencia de resguardos indígenas.', 'activo'),
(13, 'Río Caquetá', 2280.00, 1200.00, 'Amazonas', '3.5-6 pies', 'Caquetá, Putumayo, Guaviare, Amazonas', 'carga mixta, lanchas', 'ganado, madera, pescado', 'Importante ruta amazónica que conecta extensas regiones del sur de Colombia. Su navegabilidad sustenta actividades forestales y ganaderas.', 'activo'),
(14, 'Río Inírida', 1300.00, 1000.00, 'Orinoco', '2-4 pies', 'Guaviare, Guainía', 'voladoras, canoas indígenas', 'abastecimiento, ecoturismo', 'Vía hídrica vital para el Guainía y su capital, conocida por los majestuosos Cerros de Mavecure. Promueve el desarrollo turístico.', 'activo'),
(15, 'Río Negro(Guainía)', 2250.00, 250.00, 'Amazonas', '6-12 pies', 'Guainía, Venezuela, Brasil', 'barcos brasileños, lanchas', 'intercambio comercial con Brasil', 'Conecta directamente a Colombia con las rutas comerciales fluviales de Brasil en la cuenca amazónica. Es un eje de integración fronteriza.', 'activo'),
(16, 'Río Baudó', 242.00, 180.00, 'Pacífico', '2.5-4 pies', 'Chocó', 'chalupas motor, canoas', 'plátano, madera, transporte escolar', 'Línea vital de comunicación y sustento para las comunidades del medio y bajo Baudó. Asegura el transporte de alimentos y estudiantes.', 'activo'),
(17, 'Río Patía', 400.00, 120.00, 'Pacífico', '3-4.5 pies', 'Cauca, Nariño', 'lanchas rápidas, botes pesca', 'madera, plátano, pescado', 'Único río de la cordillera andina que atraviesa las montañas para desembocar en el Pacífico. Es crucial para el comercio agrícola.', 'activo'),
(18, 'Río San Jorge', 368.00, 240.00, 'Caribe/Magdalena', '2.5-4.5 pies', 'Córdoba, Sucre, Bolívar', 'planchones ganaderos, chalupas', 'ganado, arroz, maíz, pesca', 'Riega las fértiles sabanas del Caribe, siendo el motor de la Mojana sucreña y cordobesa. Su cauce es primordial para la ganadería extensiva.', 'activo'),
(19, 'Río Cesar', 280.00, 110.00, 'Magdalena', '2-3.5 pies', 'La Guajira, Cesar, Magdalena', 'canoas motor, chalupas, planchones', 'pesca, productos agrícolas', 'Alimenta importantes cuerpos de agua como la Ciénaga de Zapatosa, promoviendo la riqueza íctica regional. Facilita el transporte de cosechas.', 'activo'),
(20, 'Río Sogamoso', 135.00, 45.00, 'Magdalena', '2.5-4 pies', 'Santander', 'lanchas, canoas areneras', 'palma aceite, arena, pescado', 'Gran afluente del Magdalena que dinamiza la agroindustria palmera y extractiva en Santander. Resulta muy intensivo en el transporte de carga local.', 'activo')
